mapper.select:
SELECT tdm42_company_id
  FROM tdm42_manl_org
 WHERE tdm42_manl_org_id = #{manlOrgId}

SELECT tdm42_manl_org_id AS manl_org_id, tdm42_org_id AS org_id, tdm42_role_id AS role_id, TO_CHAR(tdm42_start_date, 'YYYY-MM-DD') AS start_date, TO_CHAR(tdm42_end_date, 'YYYY-MM-DD') AS end_date FROM tdm42_manl_org WHERE 1=1 AND tdm42_company_id = #{companyId}
AND tdm42_manl_org_id NOT IN #{item}
ORDER BY f_org_nm(tdm42_org_id, tdm42_start_date), tdm42_manl_org_id

mapper.update:
UPDATE  tdm42_manl_org
   SET  tdm42_start_date = CAST(#{startDate} AS date)
     ,  tdm42_end_date   = CAST(#{endDate} AS date)
     ,  tdm42_upd_nm     = #{updName}
     ,  tdm42_upd_date   = f_sysdate()
 WHERE  tdm42_manl_org_id = #{manlOrgId}
   AND  tdm42_company_id  = #{companyId}

UPDATE  tdm42_manl_org
   SET  tdm42_lock_yn  = #{lockYn}
     ,  tdm42_upd_nm   = #{updName}
     ,  tdm42_upd_date = f_sysdate()
 WHERE  tdm42_manl_org_id = #{manlOrgId}
   AND  tdm42_company_id  = #{companyId}
